// Groups rows by channel, computes today vs. yesterday deltas, flags simple anomalies,
// and produces a compact metrics summary for the narrative step.
const rows = items.map(i => i.json);

const byDate = {};
for (const r of rows) {
  const d = r.date;
  byDate[d] = byDate[d] || [];
  byDate[d].push(r);
}
const dates = Object.keys(byDate).sort();
const latest = dates[dates.length - 1];
const prior = dates[dates.length - 2];

function totals(dateRows) {
  const t = { spend: 0, revenue: 0, leads: 0 };
  for (const r of dateRows) {
    t.spend += Number(r.spend);
    t.revenue += Number(r.revenue);
    t.leads += Number(r.leads);
  }
  t.roas = t.spend > 0 ? +(t.revenue / t.spend).toFixed(2) : 0;
  return t;
}

const todayTotals = totals(byDate[latest] || []);
const yestTotals = prior ? totals(byDate[prior] || []) : todayTotals;

const roasDeltaPct = yestTotals.roas > 0
  ? +(((todayTotals.roas - yestTotals.roas) / yestTotals.roas) * 100).toFixed(1)
  : 0;

const anomalies = [];
for (const r of byDate[latest] || []) {
  if (Number(r.roas) < 2.2) {
    anomalies.push({ channel: r.channel, roas: Number(r.roas) });
  }
}

const monthlyBudget = 1500000; // illustrative — replace with your real monthly budget
const dayOfMonth = new Date(latest).getDate();
const expectedSpendToDate = (monthlyBudget / 30) * dayOfMonth;
const pacingPct = expectedSpendToDate > 0
  ? +(( (todayTotals.spend * dayOfMonth) / expectedSpendToDate) * 100).toFixed(0)
  : 100;

return [{
  json: {
    date: latest,
    spend: todayTotals.spend,
    revenue: todayTotals.revenue,
    leads: todayTotals.leads,
    roas: todayTotals.roas,
    roas_delta_pct: roasDeltaPct,
    anomalies: anomalies,
    budget_pacing_pct: pacingPct
  }
}];

// Builds the morning brief text from the computed metrics — no external API,
// no API key, no cost. Rule-based narrative instead of an LLM call.
const m = items[0].json;

const roasTrend = m.roas_delta_pct > 0 ? `up ${m.roas_delta_pct}%` : m.roas_delta_pct < 0 ? `down ${Math.abs(m.roas_delta_pct)}%` : 'flat';
const pacingWord = m.budget_pacing_pct > 110 ? 'ahead of pace' : m.budget_pacing_pct < 90 ? 'behind pace' : 'on pace';

let summary = `Yesterday (${m.date}): spend ₹${m.spend.toLocaleString('en-IN')}, revenue ₹${m.revenue.toLocaleString('en-IN')}, blended ROAS ${m.roas}x (${roasTrend} vs. the day before), ${m.leads} leads. Budget is ${pacingWord} at ${m.budget_pacing_pct}% of the expected monthly rate.`;

if (m.anomalies.length) {
  const names = m.anomalies.map(a => `${a.channel} (${a.roas}x)`).join(', ');
  summary += ` ${m.anomalies.length} channel(s) below the 2.2x ROAS floor: ${names}.`;
} else {
  summary += ' No channels are below the ROAS floor today.';
}

// Build exactly 3 recommended actions, prioritized by what's actually flagged.
const candidates = [];
if (m.anomalies.length) {
  candidates.push(`Review or pause: ${m.anomalies.map(a => a.channel).join(', ')} — currently below the 2.2x ROAS floor.`);
}
if (m.budget_pacing_pct > 110) {
  candidates.push('Budget is overpacing — rebalance excess spend toward the highest-ROAS channel today.');
} else if (m.budget_pacing_pct < 90) {
  candidates.push('Budget is underpacing — consider increasing spend on the best-performing channel to stay on track for the month.');
}
if (m.roas_delta_pct < -5) {
  candidates.push('Blended ROAS dropped more than 5% day-over-day — check for a creative fatigue or audience saturation signal before scaling anything.');
}
candidates.push('No anomalies beyond the above — hold current allocation and re-check tomorrow morning.');
candidates.push('Review the top 3 recommendation cards in the AI Recommendation Engine before 10 AM.');
candidates.push('Confirm yesterday\'s leads have been picked up by Sales within SLA.');

const actions = candidates.slice(0, 3);
const actionsText = actions.map((a, i) => `${i + 1}. ${a}`).join('\n');

const narrative = `${summary}\n\nRecommended actions:\n${actionsText}`;

return [{ json: { ...m, narrative } }];
